// PWA app icons. Ye files binary hoti hain, isliye yahan text (base64) me rakhi hain aur server inhe seedha serve karta hai.
// server.js me ek line chahiye:  require('./pwaIcons')(app);   (express.static wali line se PEHLE)
const ICONS = {
  'icon-192.png': '',
  'icon-512.png': '',
  'apple-touch-icon.png': ''
};

module.exports = app => {
  Object.keys(ICONS).forEach(name => {
    const buf = Buffer.from(ICONS[name], 'base64');
    app.get('/' + name, (req, res) => {
      res.set('Cache-Control', 'public, max-age=604800');
      res.type('png').send(buf);
    });
  });
};